{"hypotheses": [
  {
    "name": "Operating Profitability Minus Leverage in Positive Term Spread",
    "mechanism": "During periods with a positive term spread (indicative of steep yield curves and favorable economic conditions), highly profitable firms with low leverage should outperform because they benefit more from economic growth and lower financing costs. Combining operating profitability and negative leverage exposure in these periods captures synergistic risk-reward dynamics not realized by either factor alone.",
    "expression": {
      "terms": [
        {"weight": 1.0, "primitive": "OperProf"},
        {"weight": -1.0, "primitive": "Leverage"}
      ],
      "regime": "TERM_SPREAD_POSITIVE",
      "vol_target": true
    },
    "auxiliary_predictions": [
      {"type": "regime_interaction", "regime": "TERM_SPREAD_POSITIVE", "direction": "higher"},
      {"type": "size_segment", "segment": "large", "direction": "stronger"},
      {"type": "correlation", "primitive": "OperProf", "bound": "below", "threshold": 0.3}
    ],
    "expected_annualized_sharpe": 0.85,
    "expected_decay_half_life_months": 48
  },
  {
    "name": "Momentum Minus High Accruals with Volatility Targeting",
    "mechanism": "Stocks with strong price momentum that also exhibit low accruals avoid the risk of earnings manipulation and aggressive accounting. This combination should outperform either factor in isolation because it tilts toward sustainable winners whose earnings quality supports price trends.",
    "expression": {
      "terms": [
        {"weight": 1.0, "primitive": "Mom12m"},
        {"weight": -1.0, "primitive": "Accruals"}
      ],
      "regime": null,
      "vol_target": true
    },
    "auxiliary_predictions": [
      {"type": "regime_interaction", "regime": "MKT_TRAILING_12M_UP", "direction": "higher"},
      {"type": "size_segment", "segment": "small", "direction": "stronger"},
      {"type": "subperiod_consistency"}
    ],
    "expected_annualized_sharpe": 0.8,
    "expected_decay_half_life_months": 36
  },
  {
    "name": "Analyst Upgrades plus Organizational Capital in Low VIX Regimes",
    "mechanism": "Firms receiving analyst upgrades and exhibiting strong organizational capital are likely to outperform in periods of low market volatility (VIX below median). Analyst optimism paired with intangible asset strength indicates both near-term catalysts and durable competitive advantage, particularly when risk aversion is low.",
    "expression": {
      "terms": [
        {"weight": 1.0, "primitive": "UpRecomm"},
        {"weight": 0.5, "primitive": "OrgCap"}
      ],
      "regime": "VIX_BELOW_TRAILING_MEDIAN",
      "vol_target": false
    },
    "auxiliary_predictions": [
      {"type": "regime_interaction", "regime": "VIX_BELOW_TRAILING_MEDIAN", "direction": "higher"},
      {"type": "size_segment", "segment": "mega", "direction": "stronger"},
      {"type": "correlation", "primitive": "UpRecomm", "bound": "below", "threshold": 0.3}
    ],
    "expected_annualized_sharpe": 0.7,
    "expected_decay_half_life_months": 24
  },
  {
    "name": "Residual Momentum and Net Payout Yield under Market Downtrends",
    "mechanism": "During market downturns, combining stocks with high residual momentum (risk-adjusted outperformance) and high net payout yield (shareholder-friendly capital allocation) should deliver robust returns as investors seek both defensive performance and tangible returns.",
    "expression": {
      "terms": [
        {"weight": 1.0, "primitive": "ResidualMomentum"},
        {"weight": 0.5, "primitive": "NetPayoutYield"}
      ],
      "regime": "MKT_TRAILING_12M_DOWN",
      "vol_target": true
    },
    "auxiliary_predictions": [
      {"type": "regime_interaction", "regime": "MKT_TRAILING_12M_DOWN", "direction": "higher"},
      {"type": "size_segment", "segment": "large", "direction": "stronger"},
      {"type": "international", "region": "developed_ex_us", "direction": "same_sign"}
    ],
    "expected_annualized_sharpe": 0.9,
    "expected_decay_half_life_months": 36
  },
  {
    "name": "Asset Growth Minus Short Interest with Volatility Targeting",
    "mechanism": "Low asset growth and low short interest both historically predict higher future returns, but their combination emphasizes firms with sustainable growth and low perceived risk. This composite should deliver a premium by isolating a subset of stocks where fundamental and sentiment-based risks are simultaneously minimized.",
    "expression": {
      "terms": [
        {"weight": -1.0, "primitive": "AssetGrowth"},
        {"weight": -1.0, "primitive": "ShortInterest"}
      ],
      "regime": null,
      "vol_target": true
    },
    "auxiliary_predictions": [
      {"type": "correlation", "primitive": "AssetGrowth", "bound": "below", "threshold": 0.3},
      {"type": "size_segment", "segment": "micro", "direction": "stronger"},
      {"type": "international", "region": "emerging", "direction": "same_sign"}
    ],
    "expected_annualized_sharpe": 0.75,
    "expected_decay_half_life_months": 60
  },
  {
    "name": "Cash-Flow Yield Plus Industry Momentum",
    "mechanism": "Firms with high cash-flow yields in industries exhibiting strong momentum are likely to outperform because they combine valuation support with favorable industry trends. The intersection of cheap, cash-generating firms and positive industry sentiment reduces value traps and enhances trend persistence.",
    "expression": {
      "terms": [
        {"weight": 1.0, "primitive": "cfp"},
        {"weight": 1.0, "primitive": "IndMom"}
      ],
      "regime": null,
      "vol_target": false
    },
    "auxiliary_predictions": [
      {"type": "regime_interaction", "regime": "TERM_SPREAD_POSITIVE", "direction": "higher"},
      {"type": "correlation", "primitive": "cfp", "bound": "below", "threshold": 0.3},
      {"type": "subperiod_consistency"}
    ],
    "expected_annualized_sharpe": 0.7,
    "expected_decay_half_life_months": 48
  },
  {
    "name": "Return Seasonality and Idiosyncratic Volatility under Tight Yield Curves",
    "mechanism": "In periods of negative term spread (yield curve inversion), the combination of return seasonality and idiosyncratic volatility should outperform because persistent calendar effects interact with risk aversion, rewarding stocks with predictable seasonality and pricing in unique risk.",
    "expression": {
      "terms": [
        {"weight": 1.0, "primitive": "MomSeason"},
        {"weight": 0.5, "primitive": "IdioVol3F"}
      ],
      "regime": "TERM_SPREAD_NEGATIVE",
      "vol_target": true
    },
    "auxiliary_predictions": [
      {"type": "regime_interaction", "regime": "TERM_SPREAD_NEGATIVE", "direction": "higher"},
      {"type": "size_segment", "segment": "small", "direction": "stronger"},
      {"type": "correlation", "primitive": "MomSeason", "bound": "below", "threshold": 0.3}
    ],
    "expected_annualized_sharpe": 0.65,
    "expected_decay_half_life_months": 18
  },
  {
    "name": "Dividend Yield, Brand Investment, and Analyst Forecast Dispersion",
    "mechanism": "Stocks with high dividend yields, substantial brand investment, and low analyst forecast dispersion are likely to outperform because they combine shareholder returns, competitive advantage, and consensus-driven risk reduction. This synergy creates a robust premium that is more resilient than any single signal.",
    "expression": {
      "terms": [
        {"weight": 1.0, "primitive": "DivYieldST"},
        {"weight": 0.5, "primitive": "BrandInvest"},
        {"weight": -0.5, "primitive": "ForecastDispersion"}
      ],
      "regime": null,
      "vol_target": false
    },
    "auxiliary_predictions": [
      {"type": "size_segment", "segment": "large", "direction": "stronger"},
      {"type": "international", "region": "developed_ex_us", "direction": "same_sign"},
      {"type": "subperiod_consistency"}
    ],
    "expected_annualized_sharpe": 0.8,
    "expected_decay_half_life_months": null
  }
]}
